SELECT CASE
  WHEN RISK_BAND = 6 AND TENOR_BUCKET = 'T_LONG' THEN 1   -- leaf 0: RISK_BAND = 6 AND TENOR_BUCKET = 'T_LONG'
  WHEN RISK_BAND BETWEEN 7 AND 8 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE <= 0.2886 THEN 0   -- leaf 1: 7 <= RISK_BAND <= 8 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE <= 0.2886
  WHEN RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND AMOUNT_M <= 28 AND INTEREST_RATE > 0.32865 THEN 1   -- leaf 2: RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND AMOUNT_M <= 28 AND INTEREST_RATE > 0.32865
  WHEN RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND AMOUNT_M > 28 AND INTEREST_RATE > 0.32865 THEN 1   -- leaf 3: RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND AMOUNT_M > 28 AND INTEREST_RATE > 0.32865
  WHEN RISK_BAND = 7 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.2886 THEN 1   -- leaf 4: RISK_BAND = 7 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.2886
  WHEN RISK_BAND = 8 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.2886 THEN 1   -- leaf 5: RISK_BAND = 8 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.2886
  WHEN RISK_BAND = 5 AND TENOR_BUCKET = 'T_LONG' THEN 1   -- leaf 6: RISK_BAND = 5 AND TENOR_BUCKET = 'T_LONG'
  WHEN RISK_BAND = 5 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE <= 0.2947 THEN 0   -- leaf 7: RISK_BAND = 5 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE <= 0.2947
  WHEN RISK_BAND = 5 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE > 0.2947 THEN 1   -- leaf 8: RISK_BAND = 5 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE > 0.2947
  WHEN RISK_BAND = 2 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.35015 THEN 1   -- leaf 9: RISK_BAND = 2 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.35015
  WHEN RISK_BAND = 2 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.35015 THEN 1   -- leaf 10: RISK_BAND = 2 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.35015
  WHEN RISK_BAND = 4 AND TENOR_BUCKET = 'T_LONG' THEN 1   -- leaf 11: RISK_BAND = 4 AND TENOR_BUCKET = 'T_LONG'
  WHEN RISK_BAND = 4 AND TENOR_BUCKET = 'T_MID' THEN 1   -- leaf 12: RISK_BAND = 4 AND TENOR_BUCKET = 'T_MID'
  WHEN RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE <= 0.2991 THEN 0   -- leaf 13: RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE <= 0.2991
  WHEN RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE > 0.2991 AND INTEREST_RATE <= 0.32865 THEN 0   -- leaf 14: RISK_BAND = 6 AND TENOR_BUCKET = 'T_MID' AND 0.2991 < INTEREST_RATE <= 0.32865
  WHEN RISK_BAND >= 9 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE <= 0.33485 THEN 0   -- leaf 15: RISK_BAND >= 9 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE <= 0.33485
  WHEN RISK_BAND >= 9 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.33485 THEN 0   -- leaf 16: RISK_BAND >= 9 AND TENOR_BUCKET = 'T_LONG' AND INTEREST_RATE > 0.33485
  WHEN RISK_BAND = 3 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.35165 THEN 0   -- leaf 17: RISK_BAND = 3 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.35165
  WHEN RISK_BAND = 3 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.35165 THEN 1   -- leaf 18: RISK_BAND = 3 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.35165
  WHEN RISK_BAND >= 8 AND TENOR_BUCKET NOT IN ('T_LONG') THEN 0   -- leaf 19: RISK_BAND >= 8 AND TENOR_BUCKET != 'T_LONG'
  WHEN RISK_BAND = 7 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3783 THEN 0   -- leaf 20: RISK_BAND = 7 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3783
  WHEN RISK_BAND = 7 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE > 0.3783 THEN 0   -- leaf 21: RISK_BAND = 7 AND TENOR_BUCKET = 'T_MID' AND INTEREST_RATE > 0.3783
  WHEN RISK_BAND <= 0 AND TENOR_BUCKET = 'T_SHORT' THEN 1   -- leaf 22: RISK_BAND <= 0 AND TENOR_BUCKET = 'T_SHORT'
  WHEN RISK_BAND = 1 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.3125 THEN 1   -- leaf 23: RISK_BAND = 1 AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE <= 0.3125
  WHEN RISK_BAND = 1 AND PRODUCT_GROUP NOT IN ('CLX_SMALL') AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3125 THEN 1   -- leaf 24: RISK_BAND = 1 AND PRODUCT_GROUP != 'CLX_SMALL' AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3125
  WHEN RISK_BAND = 1 AND PRODUCT_GROUP = 'CLX_SMALL' AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3125 THEN 1   -- leaf 25: RISK_BAND = 1 AND PRODUCT_GROUP = 'CLX_SMALL' AND TENOR_BUCKET = 'T_SHORT' AND INTEREST_RATE > 0.3125
  WHEN RISK_BAND <= 2 AND TENOR_BUCKET NOT IN ('T_SHORT') THEN 1   -- leaf 26: RISK_BAND <= 2 AND TENOR_BUCKET != 'T_SHORT'
  WHEN RISK_BAND = 3 AND TENOR_BUCKET NOT IN ('T_SHORT') THEN 1   -- leaf 27: RISK_BAND = 3 AND TENOR_BUCKET != 'T_SHORT'
  WHEN RISK_BAND = 7 AND TENOR_BUCKET NOT IN ('T_LONG') AND INTEREST_RATE <= 0.35775 THEN 0   -- leaf 28: RISK_BAND = 7 AND TENOR_BUCKET != 'T_LONG' AND INTEREST_RATE <= 0.35775
  WHEN RISK_BAND = 7 AND TENOR_BUCKET NOT IN ('T_LONG') AND INTEREST_RATE > 0.35775 AND INTEREST_RATE <= 0.3783 THEN 0   -- leaf 29: RISK_BAND = 7 AND TENOR_BUCKET != 'T_LONG' AND 0.35775 < INTEREST_RATE <= 0.3783
  WHEN RISK_BAND = 4 AND TENOR_BUCKET = 'T_SHORT' THEN 0   -- leaf 30: RISK_BAND = 4 AND TENOR_BUCKET = 'T_SHORT'
  WHEN RISK_BAND BETWEEN 5 AND 6 AND TENOR_BUCKET = 'T_SHORT' THEN 0   -- leaf 31: 5 <= RISK_BAND <= 6 AND TENOR_BUCKET = 'T_SHORT'
END AS APPROVE_ACTION
FROM applications;